compile.workshop:
variables {
    global:
        0: arr
        1: n
        2: i
        3: code
        127: __emptyString__
    player:
        0: parr
        1: pn
        2: pi
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(__emptyString__, Char In String(Empty Array, Null));
    }
}

//Optimize for size enabled
rule ("values") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(n, Global.__emptyString__);
        Modify Global Variable(arr, Subtract, Global.__emptyString__);
        Modify Global Variable(arr, Append To Array, Global.__emptyString__);
        Modify Global Variable(arr, Remove From Array By Value, Global.__emptyString__);
        Modify Global Variable At Index(arr, False, Subtract, Global.__emptyString__);
        Modify Global Variable At Index(arr, False, Append To Array, Global.__emptyString__);
        Modify Player Variable(Event Player, parr, Append To Array, Global.__emptyString__);
        Modify Player Variable(Event Player, pn, Subtract, Global.__emptyString__);
        Modify Global Variable(n, Min, Global.__emptyString__);
        Modify Global Variable(n, Max, Global.__emptyString__);
        For Global Variable(i, 0, Global.__emptyString__, True);
        End;
        For Global Variable(i, Global.__emptyString__, 5, True);
        End;
        For Global Variable(i, 1, 5, Global.__emptyString__);
        End;
        For Player Variable(Event Player, pi, 0, Global.__emptyString__, True);
        End;
        Set Global Variable(arr, Array(Global.__emptyString__, Custom String("x")));
        If(True);
            Skip(Value In Array(Array(1, Null), Add(True, Index Of Array Value(Array(Global.__emptyString__), Global.code))));
        //__label_switch_2_0__:
        Set Global Variable(n, 1);
        //__label_switch_2_default__:
        Set Global Variable(n, 2);
        End;
    }
}

